function restoreRememberedLogin(): void { if(isset($_SESSION['user'])||empty($_COOKIE['zynko_remember']))return; try{$raw=$_COOKIE['zynko_remember'];[$id,$token]=array_pad(explode('.', $raw,2),2,'');if(!$id||!$token)return;$st=appDb()->prepare("SELECT s.user_id,u.name,u.email,u.locale,u.avatar_path,tu.tenant_id,tu.role_code,t.name company,t.status tenant_status FROM user_sessions s JOIN users u ON u.id=s.user_id JOIN tenant_users tu ON tu.user_id=u.id JOIN tenants t ON t.id=tu.tenant_id WHERE s.id=? AND s.token_hash=? AND s.remember_me=1 AND s.revoked_at IS NULL AND s.expires_at>NOW() AND u.status='active' LIMIT 1");$st->execute([(int)$id,hash('sha256',$token)]);$u=$st->fetch();if(!$u)return;session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['user_id'],'name'=>$u['name'],'email'=>$u['email'],'avatar_path'=>$u['avatar_path']??null,'tenant_id'=>(int)$u['tenant_id'],'company'=>$u['company'],'role'=>$u['role_code'],'locale'=>$u['locale']];$_SESSION['zynko_session_row_id']=(int)$id;}catch(Throwable $e){} }
ensureRuntimeSchema(); restoreRememberedLogin();
// Track legacy/already-open PHP sessions too, so Administrar usuarios always shows the current access.
if(isset($_SESSION['user']) && empty($_SESSION['zynko_session_row_id'])){try{$uid=(int)$_SESSION['user']['id'];$ip=$_SERVER['REMOTE_ADDR']??'';$ua=substr($_SERVER['HTTP_USER_AGENT']??'',0,500);$tokenHash=hash('sha256','php:'.session_id().':'.bin2hex(random_bytes(16)));$exp=(new DateTimeImmutable('+12 hours'))->format('Y-m-d H:i:s');$q=appDb()->prepare('INSERT INTO user_sessions(user_id,token_hash,remember_me,ip_address,user_agent,expires_at) VALUES(?,?,0,?,?,?)');$q->execute([$uid,$tokenHash,$ip,$ua,$exp]);$_SESSION['zynko_session_row_id']=(int)appDb()->lastInsertId();}catch(Throwable $e){}}
if(isset($_SESSION['user'],$_SESSION['zynko_session_row_id'])){try{$q=appDb()->prepare('SELECT 1 FROM user_sessions WHERE id=? AND user_id=? AND revoked_at IS NULL AND expires_at>NOW()');$q->execute([(int)$_SESSION['zynko_session_row_id'],(int)$_SESSION['user']['id']]);if(!$q->fetchColumn()){$_SESSION=[];session_destroy();header('Location: ?page=login');exit;}}catch(Throwable $e){}}

if($_SERVER['REQUEST_METHOD']==='POST' && isset($_SESSION['user']) && str_starts_with($_POST['action']??'','ajax_')===false && isset($_SERVER['HTTP_X_ZYNKO_AJAX'])){
 try{$pdo=appDb();$tid=(int)$_SESSION['user']['tenant_id'];$action=$_POST['action']??'';
  if($action==='system_version_save'){if(!isPlatformOwner())throw new RuntimeException('No autorizado.');$v=trim($_POST['version']??'');if(!preg_match('/^\d+\.\d+\.\d+$/',$v))throw new RuntimeException('Usa el formato 2.23.1.');$pdo->prepare("INSERT INTO system_settings(setting_key,setting_value,updated_by) VALUES('app_version',?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)")->execute([$v,(int)$_SESSION['user']['id']]);jsonOut(true,'Versión actualizada a '.$v.'.');}
  if($action==='email_test'){require_once $root.'/app/Services/NotificationService.php';$to=trim((string)($_SESSION['user']['email']??''));$res=(new NotificationService($pdo,$root))->sendTest($tid,$to);if(empty($res['success']))throw new RuntimeException($res['message']??'No se pudo enviar la prueba.');jsonOut(true,'Correo de prueba enviado a '.$to.'.');}
